def solve(inputs: dict) -> float:
    import re
    # Parse matrix M, power p, modulus m from inputs
    M = None
    p = None
    mod = None
    for k, v in inputs.items():
        kl = str(k).lower()
        if isinstance(v, (list, tuple)):
            M = v
        elif 'pow' in kl or 'power' in kl or 'exp' in kl or kl == 'n' or kl == 'k':
            p = int(v)
        elif 'mod' in kl:
            mod = int(v)

    # Fallback: scan for numbers if not found
    if M is None or p is None or mod is None:
        # try to parse from a text field
        text = None
        for k, v in inputs.items():
            if isinstance(v, str):
                text = v
        if text is not None:
            nums = list(map(int, re.findall(r'-?\d+', text)))
            # matrix entries, power, modulus heuristic
            if M is None and len(nums) >= 4:
                M = [[nums[0], nums[1]], [nums[2], nums[3]]]
            if p is None and len(nums) >= 5:
                p = nums[4]
            if mod is None and len(nums) >= 6:
                mod = nums[5]

    n = len(M)
    def matmul(A, B):
        C = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                s = 0
                for kk in range(n):
                    s += A[i][kk]*B[kk][j]
                C[i][j] = s % mod
        return C

    # identity
    R = [[1 if i==j else 0 for j in range(n)] for i in range(n)]
    base = [[M[i][j] % mod for j in range(n)] for i in range(n)]
    e = p
    while e > 0:
        if e & 1:
            R = matmul(R, base)
        base = matmul(base, base)
        e >>= 1

    total = 0
    for i in range(n):
        for j in range(n):
            total += R[i][j]
    return float(total)

